UPDATE asset_usage
SET status_code = #{status}, returned_dttm = #{returnedDttm},
    processed_by_member_id = #{processedByMemberId}
WHERE asset_usage_id = #{assetUsageId}

UPDATE asset_unit
SET status_code = #{status}, storage_location = #{storageLocation}
WHERE asset_unit_id = #{assetUnitId}

UPDATE asset_unit
SET status_code = #{status}
